    // pasted into the dial/secret prompts), like typed characters do.
    if (prompt != null) {
      final key = PromptPaste(content);
      final (state: next, resolved: answer) = handleTuiPromptKey(prompt!, key);
      if (answer != null) {
        _promptCompleter?.complete(answer);
